properties.query:
let ingestionTime = ingestion_time();  
let MonitoredAssets = _GetWatchlist("TableOfflineIndex")
| where Frequency == "High"
| summarize by Name, Frequency, Maintenance
| project-rename Table = Name;
// Get all available tables most recent logs
let Tab1 = (
    AllTableNames
    | where ingestionTime > ago(1d)
    | extend Table = tostring(tablename)
    | summarize Last_seen = max(ingestionTime), Last_count = count() by Table
);
// Get all vendors and products within common security logs most recent log
let Tab2 = (
    AllTableNames
    | where ingestionTime > ago(1d)
    | extend Table_ = tostring(tablename)
    | where Table_ == "CommonSecurityLog"
    | as cache
    | extend Table = DeviceVendor
    | union (cache | extend Table = DeviceProduct)
    | summarize Last_seen = max(ingestionTime), Last_count = count() by Table
);
// Get all products from within SecurityAlerts most recent log
let Tab3 = (
    AllTableNames
    | where ingestionTime > ago(1d)
    | extend Table_ = tostring(tablename)
    | where Table_ == "SecurityAlert"
    | extend Table = ProductName
    | summarize Last_seen = max(ingestionTime), Last_count = count() by Table
);
// Get all products from within ASimTables most recent log
let Tab4 = (
    AllTableNames
    | where ingestionTime > ago(1d)
    | extend Table_ = tostring(tablename)
    | where Table_ has_any ("ASimNetworkSessionLogs", "ASimDnsActivityLogs")
    | extend Table = EventProduct
    | summarize Last_seen = max(ingestionTime), Last_count = count() by Table
);
let MergedTables = union Tab1, Tab2, Tab3, Tab4;
MergedTables
| join kind=inner (MonitoredAssets) on Table
| where tolower(Maintenance) !~ "true" // exclude entries under maintenance (case insensitive)
| extend timenow = now()
| extend time_diff = datetime_diff("minute", timenow, Last_seen)
| extend OverTimeDiff = 60 // High - 1 hour threshold
| where time_diff >= OverTimeDiff
| extend Override = strcat("Table: '", Table, "' last received a log at '", format_datetime(Last_seen, 'yyyy-M-dd HH:mm:ss'), "', this violates the defined allowed downtime for this source by '",  time_diff, "' minutes. Allowed downtime for this specific source is, '", OverTimeDiff, "' minutes.\n")
